-- TPC-DS Test_Query Query 103
-- Based on: query13.tpl (medium)
-- Variation: 40

select avg(ss_quantity) ,avg(ss_ext_sales_price) ,avg(ss_ext_wholesale_cost) ,sum(ss_ext_wholesale_cost) from store_sales ,store ,customer_demographics ,household_demographics ,customer_address ,date_dim where s_store_sk = ss_store_sk and  ss_sold_date_sk = d_date_sk and d_year = 2033 and((ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.1' and cd_education_status = 'ES.3' and ss_sales_price between 100.2 and 150.1 and hd_dep_count = 2 )or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.1' and ss_sales_price between 50.1 and 100.1 and hd_dep_count = 3 ) or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.5' and ss_sales_price between 150.1 and 200.1 and hd_dep_count = 2 )) and((ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.1', 'STATE.4', 'STATE.5') and ss_net_profit between 103 and 192 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.6', 'STATE.3', 'STATE.6') and ss_net_profit between 153 and 302 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.9', 'STATE.7', 'STATE.9') and ss_net_profit between 48 and 242 ));
